def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell value can be collected at most once, even if both paths pass through it.
    """
    if N <= 0:
        return 0

    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = v

    # Edge case: single cell grid
    if N == 1:
        return grid[1][1]

    # Initialize DP arrays
    NEG_INF = -10**18
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    # Iterate over all possible sums of coordinates (k = i1 + j1 = i2 + j2)
    for k in range(3, 2 * N + 1):
        # Reset current DP layer
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                dp_cur[i][j] = NEG_INF

        # i1 and i2 range for current k
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue

                best_prev = NEG_INF
                # Four possible previous moves
                for di1 in (0, 1):
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        val = dp_prev[pi1][pi2]
                        if val > best_prev:
                            best_prev = val
                if best_prev == NEG_INF:
                    continue

                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                dp_cur[i1][i2] = best_prev + add

        # Swap layers
        dp_prev, dp_cur = dp_cur, dp_prev

    result = dp_prev[N][N]
    return result if result != NEG_INF else 0

def max_product(num_str: str, N: int, K: int) -> int:
    if N != len(num_str):
        N = len(num_str)
    if N == 0:
        return 0
    if K < 0 or K > N-1:
        return 0
    if K == 0:
        return int(num_str)
    # dp[i][k] for i digits, k cuts
    dp = [[0]*(K+1) for _ in range(N+1)]
    # base k=0
    for i in range(1, N+1):
        dp[i][0] = int(num_str[:i])
    # compute for k>=1
    for i in range(1, N+1):
        # compute substring values ending at i
        sub_val = [0]*i
        num = 0
        multiplier = 1
        for j in range(i-1, -1, -1):
            num += int(num_str[j]) * multiplier
            multiplier *= 10
            sub_val[j] = num
        # for k from 1 to min(K, i-1)
        max_k = min(K, i-1)
        for k in range(1, max_k+1):
            best = 0
            # j from k to i-1
            for j in range(k, i):
                candidate = dp[j][k-1] * sub_val[j]
                if candidate > best:
                    best = candidate
            dp[i][k] = best
    return dp[N][K]

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
                              as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.

    Examples:
    >>> generate_numbers(234, [(2, 5), (3, 6)])
    4
    >>> generate_numbers(100, [(1, 9)])
    2
    """
    # Input validation
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples")
    for rule in rules:
        if (
            not isinstance(rule, tuple)
            or len(rule) != 2
            or not all(isinstance(d, int) and 0 <= d <= 9 for d in rule)
        ):
            raise ValueError("Each rule must be a tuple of two integers between 0 and 9")

    start = str(n)
    visited = {start}
    queue = [start]

    while queue:
        current = queue.pop(0)
        for idx, ch in enumerate(current):
            digit = int(ch)
            for x, y in rules:
                if digit == x:
                    new_num = current[:idx] + str(y) + current[idx + 1 :]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def min_remaining_space(V, n, volumes):
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.

    This function uses a dynamic programming approach to determine the maximum volume that can be occupied
    in the box by any subset of the given items. It then returns the difference between the box's total capacity
    and this maximum occupied volume, which is the minimum remaining space.

    Args:
    - V (int): The total capacity of the box.
    - n (int): The number of items to consider for packing into the box.
    - volumes (List[int]): A list of the volumes of the n items.

    Returns:
    - int: The minimum remaining space in the box after fitting the items.
    """
    # Basic validation
    if not isinstance(V, int) or V < 0:
        raise ValueError("Box capacity V must be a non‑negative integer.")
    if not isinstance(n, int) or n < 0:
        raise ValueError("Number of items n must be a non‑negative integer.")
    if not isinstance(volumes, list):
        raise ValueError("volumes must be a list of integers.")
    if n != len(volumes):
        raise ValueError("Length of volumes list must match n.")
    for v in volumes:
        if not isinstance(v, int) or v < 0:
            raise ValueError("All item volumes must be non‑negative integers.")

    # Edge case: no items or empty box
    if n == 0 or V == 0:
        return V

    # Dynamic programming: boolean array of achievable sums up to V
    achievable = [False] * (V + 1)
    achievable[0] = True

    for vol in volumes:
        if vol == 0:
            continue  # zero volume items don't change achievable sums
        # iterate backwards to avoid using an item multiple times
        for cap in range(V, vol - 1, -1):
            if achievable[cap - vol]:
                achievable[cap] = True

    # Find the largest achievable sum <= V
    max_occupied = 0
    for cap in range(V, -1, -1):
        if achievable[cap]:
            max_occupied = cap
            break

    return V - max_occupied

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    n = len(heights)
    if n <= 1:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1  # peak counted twice
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic
